def transform(grid):
    g = np.array(grid)
    bg = background(g)
    ring_colour = {3: 6, 8: 4, 2: 1}
    out = g.copy()
    H, W = g.shape
    emit(out, "Start from the input: isolated single pixels on the background.")
    for o in objects(g, bg=bg):
        c = o["colour"]
        if c not in ring_colour:
            continue
        rc = ring_colour[c]
        for (y, x) in o["cells"]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W and out[yy, xx] == bg:
                        out[yy, xx] = rc
        y0, x0, _, _ = o["box"]
        emit(out, f"Surround the colour-{c} pixel at ({y0},{x0}) with a 3x3 ring of colour {rc} (legend {c}->{rc}).")
    emit(out, "All pixels are framed; final output.")
    return out
